mapper.select:
SELECT * FROM ( SELECT a.*, ROWNUM rnum FROM ( SELECT ,
FROM TB_LOGISTICS_DIRECT_RETURN ldr LEFT JOIN TB_RETURN_ITEM ri ON ldr.MATCHED_RETURN_ID = ri.RETURN_ID
ORDER BY
ldr.RECEIVED_DATE ldr.CUSTOMER_NAME ldr.MAPPING_STATUS ldr.PROCESSING_STATUS ldr.DIRECT_RETURN_ID
ASC DESC
) a WHERE ROWNUM <= #{search.endRow} ) WHERE rnum > #{search.offset}

