mapper.update:
UPDATE TB_LOGISTICS_DIRECT_RETURN SET
    PROCESSING_STATUS = #{processingStatus},
    UPDATED_DATE = SYSTIMESTAMP,
    UPDATED_BY = #{updatedBy}
WHERE DIRECT_RETURN_ID IN

