mapper.select:
SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END
FROM TB_LOGISTICS_DIRECT_RETURN
WHERE TRACKING_NUMBER = #{trackingNumber}

    AND DIRECT_RETURN_ID != #{excludeId}
